CREATE OR REPLACE FUNCTION phase4_protect_invoice_history() RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'DELETE' AND OLD."status" NOT IN ('DRAFT', 'APPROVED') THEN RAISE EXCEPTION 'Posted invoices are immutable'; END IF;
  IF TG_OP = 'UPDATE' AND OLD."status" NOT IN ('DRAFT', 'APPROVED') THEN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
      (OLD."status" = 'POSTED' AND NEW."status" IN ('VOIDED','PARTIALLY_CREDITED','CREDITED','PARTIALLY_PAID','PAID'))
      OR (OLD."status" = 'PARTIALLY_PAID' AND NEW."status" IN ('PAID','PARTIALLY_CREDITED','CREDITED'))
      OR (OLD."status" = 'PARTIALLY_CREDITED' AND NEW."status" IN ('PARTIALLY_PAID','PAID','CREDITED'))
    ) THEN RAISE EXCEPTION 'Posted invoice status transition is not permitted'; END IF;
    IF NEW."amountPaidMinor" IS DISTINCT FROM OLD."amountPaidMinor" AND NEW."amountPaidMinor" <> COALESCE((SELECT SUM("amountMinor") FROM "PaymentAllocation" WHERE "invoiceId" = OLD."id"), 0) THEN RAISE EXCEPTION 'Invoice payment total must equal immutable allocations'; END IF;
    IF NEW."customerId" IS DISTINCT FROM OLD."customerId" OR NEW."provisionalIdentifier" IS DISTINCT FROM OLD."provisionalIdentifier" OR NEW."invoiceNumber" IS DISTINCT FROM OLD."invoiceNumber" OR NEW."issueDate" IS DISTINCT FROM OLD."issueDate" OR NEW."dueDate" IS DISTINCT FROM OLD."dueDate" OR NEW."paymentTermsDays" IS DISTINCT FROM OLD."paymentTermsDays" OR NEW."currency" IS DISTINCT FROM OLD."currency" OR NEW."subtotalMinor" IS DISTINCT FROM OLD."subtotalMinor" OR NEW."discountTotalMinor" IS DISTINCT FROM OLD."discountTotalMinor" OR NEW."taxTotalMinor" IS DISTINCT FROM OLD."taxTotalMinor" OR NEW."grandTotalMinor" IS DISTINCT FROM OLD."grandTotalMinor" OR NEW."journalId" IS DISTINCT FROM OLD."journalId" OR NEW."postedAt" IS DISTINCT FROM OLD."postedAt" OR NEW."postedByUserId" IS DISTINCT FROM OLD."postedByUserId" OR NEW."approvedAt" IS DISTINCT FROM OLD."approvedAt" OR NEW."approvedByUserId" IS DISTINCT FROM OLD."approvedByUserId" OR NEW."customerNameSnapshot" IS DISTINCT FROM OLD."customerNameSnapshot" OR NEW."customerEmailSnapshot" IS DISTINCT FROM OLD."customerEmailSnapshot" OR NEW."billingAddressSnapshot" IS DISTINCT FROM OLD."billingAddressSnapshot" OR NEW."serviceAddressSnapshot" IS DISTINCT FROM OLD."serviceAddressSnapshot" OR NEW."organizationSnapshot" IS DISTINCT FROM OLD."organizationSnapshot" OR NEW."customerFacingNotes" IS DISTINCT FROM OLD."customerFacingNotes" OR NEW."internalNotes" IS DISTINCT FROM OLD."internalNotes" OR NEW."terms" IS DISTINCT FROM OLD."terms" OR NEW."createdByUserId" IS DISTINCT FROM OLD."createdByUserId" OR NEW."createdAt" IS DISTINCT FROM OLD."createdAt" THEN RAISE EXCEPTION 'Posted invoice financial and audit history is immutable'; END IF;
    IF NEW."status" IN ('PARTIALLY_CREDITED', 'CREDITED') AND NOT EXISTS (SELECT 1 FROM "CreditNote" WHERE "organizationId" = OLD."organizationId" AND "invoiceId" = OLD."id" AND "status" = 'POSTED') THEN RAISE EXCEPTION 'Credit status requires a posted credit note'; END IF;
    IF NEW."status" = 'VOIDED' AND NOT EXISTS (SELECT 1 FROM "Journal" WHERE "organizationId" = OLD."organizationId" AND "reversedJournalId" = OLD."journalId" AND "status" = 'POSTED') THEN RAISE EXCEPTION 'Voiding requires a posted reversal'; END IF;
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END; $$ LANGUAGE plpgsql;
